{\cite[Corollaries 6.2 and 6.3]{M23}} \label{Cor6.2} Let $m,n$, and $r$ be nonnegative integers such that $0\leq r<m$. Then \begin{itemize}\item[(i)] $\displaystyle \sum_{j=0}^\infty (-1)^{j+1} a_{m,r}(n-3j(j+1)/2)= \sum_{j=0}^\infty (mj+r)G(n-mj-r)$
\item[(ii)] $\displaystyle \sum_{j=1}^\infty (-1)^{j+1} s_{m}(n-3j(j+1)/2)= \sum_{j=0}^\infty jG(n-mj)$.
\end{itemize}
